from __future__ import annotations

from typing import Any

import argon2_hasher
import pbkdf2_hasher
import scrypt_hasher
import bcrypt_hasher


def register_password(password: str) -> str:
    """
    Hash a newly registered user's password for storage.

    Per org policy: new password hashes must follow the current OWASP Password
    Storage Cheat Sheet. This deployment uses Argon2id for new hashes.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")

    # Argon2id is the current first-choice algorithm for new hashes.
    return argon2_hasher.hash_argon2(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against any supported stored hash format.

    Legacy formats remain verifiable to allow users to log in and be re-hashed.
    """
    if not isinstance(password, str) or not isinstance(stored, str):
        raise TypeError("password and stored must be str")

    # Dispatch by prefix when possible, but fall back to a full try-set.
    # (This avoids false negatives if an encoding differs slightly.)
    try:
        if stored.startswith("argon2id$"):
            return argon2_hasher.verify_argon2(password, stored)
        if stored.startswith("$scrypt$") or stored.startswith("scrypt$"):
            return scrypt_hasher.verify_scrypt(password, stored)
        if stored.startswith("$pbkdf2-") or stored.startswith("pbkdf2-"):
            return pbkdf2_hasher.verify_pbkdf2(password, stored)
        if stored.startswith("$2a$") or stored.startswith("$2b$") or stored.startswith("$2y$"):
            return bcrypt_hasher.verify_bcrypt(password, stored)
    except Exception:
        # If prefix-based verification blows up for a malformed hash, treat as non-match.
        return False

    # Fallback: try all verifiers (legacy verification is always permitted).
    for verifier in (argon2_hasher.verify_argon2, scrypt_hasher.verify_scrypt, pbkdf2_hasher.verify_pbkdf2, bcrypt_hasher.verify_bcrypt):
        try:
            if verifier(password, stored):
                return True
        except Exception:
            continue

    return False

from __future__ import annotations

from typing import Literal

import pbkdf2_hasher


Digest = Literal["sha256", "sha512", "sha1"]


def fips_password_hash(password: str, digest: Digest) -> str:
    """
    Hash a password using PBKDF2-HMAC for FIPS mode only.

    Returns:
        "$pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>"
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(digest, str):
        raise TypeError("digest must be a str")

    digest_l = digest.lower()
    if digest_l not in ("sha256", "sha512", "sha1"):
        raise ValueError("digest must be one of: sha256, sha512, sha1")

    # Delegates parameter selection + encoding/formatting to the provided skill module.
    return pbkdf2_hasher.hash_pbkdf2(password, digest_l)


def fips_verify(password: str, stored: str) -> bool:
    """
    Verify a password against a stored PBKDF2-HMAC hash.

    Only supports PBKDF2 stored hashes in the format produced by fips_password_hash,
    but will accept any $pbkdf2-<digest>$<iterations>$...$... value that the skill verifies.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(stored, str):
        raise TypeError("stored must be a str")

    # Verify using the provided skill module (supports any pbkdf2 digest/iterations encoded).
    try:
        # pbkdf2_hasher.verify_pbkdf2 may raise on malformed encodings; treat those as failures.
        return pbkdf2_hasher.verify_pbkdf2(password, stored)
    except Exception:
        return False

from __future__ import annotations

from typing import Final

import argon2_hasher
import bcrypt_hasher
import pbkdf2_hasher
import scrypt_hasher


# Known formats (as produced/accepted by the skill modules)
_PREFIX_ARGON2: Final[str] = "$argon2id$"
_PREFIX_PBKDF2: Final[str] = "$pbkdf2-"
_PREFIX_SCRYPT: Final[str] = "$scrypt$"
_PREFIX_BCRYPT_ANY: Final[tuple[str, ...]] = ("$2a$", "$2b$", "$2y$")


def register_password(password: str) -> str:
    """
    Hash a newly registered user's password following the organisation's current policy.

    New hashes must follow the OWASP Password Storage Cheat Sheet revision in force.
    In this deployment: Argon2id is used for new hashes.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    return argon2_hasher.hash_argon2(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against any supported stored hash format, including legacy ones.

    Supports:
      - Argon2id ($argon2id$...)
      - scrypt ($scrypt$...)
      - PBKDF2 ($pbkdf2-<digest>$...)
      - bcrypt ($2a$/$2b$/$2y$...)
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(stored, str):
        raise TypeError("stored must be a str")

    if stored.startswith(_PREFIX_ARGON2):
        return argon2_hasher.verify_argon2(password, stored)

    if stored.startswith(_PREFIX_SCRYPT):
        return bool(scrypt_hasher.verify_scrypt(password, stored))

    if stored.startswith(_PREFIX_PBKDF2):
        return bool(pbkdf2_hasher.verify_pbkdf2(password, stored))

    if stored.startswith(_PREFIX_BCRYPT_ANY):
        return bool(bcrypt_hasher.verify_bcrypt(password, stored))

    # Unknown / unsupported format
    return False

from __future__ import annotations

from typing import Final

import pbkdf2_hasher

_ALLOWED_DIGESTS: Final[set[str]] = {"sha256", "sha512", "sha1"}


def fips_password_hash(password: str, digest: str) -> str:
    """
    FIPS-mode password hashing using PBKDF2-HMAC only.

    Returns a string in the format:
      $pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>

    digest must be one of: "sha256", "sha512", "sha1".
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(digest, str):
        raise TypeError("digest must be a str")

    d = digest.lower().strip()
    if d not in _ALLOWED_DIGESTS:
        raise PermissionError("FIPS-mode PBKDF2-HMAC only allows sha256, sha512, or sha1")

    # Delegate parameter selection and encoding to the provided skill.
    return pbkdf2_hasher.hash_pbkdf2(password, d)


def fips_verify(password: str, stored: str) -> bool:
    """
    Verify a password against any stored $pbkdf2-* hash (any digest/iteration count).
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(stored, str):
        raise TypeError("stored must be a str")

    return pbkdf2_hasher.verify_pbkdf2(password, stored)

