def register_password(password: str) -> str:
    """
    Hash a newly registered user's password according to current org policy.

    Policy: New password hashes must follow the current OWASP Password Storage
    Cheat Sheet revision. In this deployment, Argon2id is the primary algorithm.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")

    # New hashes: Argon2id only (per org policy + available algorithms).
    return argon2_hasher.hash_argon2(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against a stored password hash.

    Supports:
      - newly registered hashes from register_password (Argon2id PHC format)
      - legacy stored hashes of older formats (always permitted to verify)
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(stored, str):
        return False

    # Try Argon2id first (new primary format)
    try:
        if argon2_hasher.verify_argon2(password, stored):
            return True
    except Exception:
        # Be conservative: continue to legacy verification.
        pass

    # Legacy formats
    try:
        if scrypt_hasher.verify_scrypt(password, stored):
            return True
    except Exception:
        pass

    try:
        if pbkdf2_hasher.verify_pbkdf2(password, stored):
            return True
    except Exception:
        pass

    try:
        if bcrypt_hasher.verify_bcrypt(password, stored):
            return True
    except Exception:
        pass

    return False
